class Solution {
    public int[] nextGreaterElement(int[] nums1, int[] nums2) {
        int[] ans = new int[nums1.length];
        for (int q = 0; q < nums1.length; q++) {
            int j = 0;
            while (nums2[j] != nums1[q]) j++;
            ans[q] = -1;
            for (int k = j + 1; k < nums2.length; k++)
                if (nums2[k] > nums1[q]) { ans[q] = nums2[k]; break; }
        }
        return ans;
    }
}

